import Dialog from "@mui/material/Dialog";
import { useEffect, useState } from "react";
import {  callAPIWithoutAuth } from "../../../utils/apiUtils";
import { apiUrls } from "../../../utils/apiUrls";
import { ApiLoder, ErrorMessage } from "../../../helpers/common";
import ExportFile from "../../../helpers/ExportFile";
import { defaultConfig } from "../../../config";
import { Link } from "react-router-dom";
// import { Link } from "react-router-dom";

const Breakdown = ({ open, handleClose, data,EstimateId="",IsView=false }) => {
  const [tenantList, setTenantList] = useState([]);
  const [show, setShow] = useState(false);
  const TenantlistAPI = async () => {
    let query = {
      WindowProductIds: [data.windowProdcutId],
      IsBreakDown: true,
      EstimateId:EstimateId,
      IsView:IsView
    };
    try {
      setShow(true);
      const apiResponse = await callAPIWithoutAuth(
        apiUrls.BuildEstimate,
        {},
        "POST",
        query
      );
      setShow(false);
      if (apiResponse?.data?.isSuccess) {
        setTenantList(apiResponse?.data?.data);
      } else {
        setTenantList([]);
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setShow(false);
    }
  };
  useEffect(() => {
    if (data.windowProdcutId) {
      TenantlistAPI();
    }
    // eslint-disable-next-line
  }, [open]);
  const token = localStorage.getItem("accessToken");
  return (
    <>
      <Dialog
        open={open}
        sx={{
          "& .MuiDialog-container": {
            "& .MuiPaper-root": {
              width: "100%",
              maxWidth: "800px",
            },
          },
        }}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <div
          className="modal fade show"
          id="contactModal"
          tabIndex={-1}
          aria-labelledby="exampleModalLabel"
          aria-modal="true"
          role="dialog"
          style={{ display: "block", backgroundColor: "#00000080" }}
        >
          <div
            className="modal-dialog modal-dialog-centered filter_modal"
            style={{ maxWidth: "90%" }}
          >
            <div className="modal-content">
              <div className="modal-header">
                <h1 className="modal-title" id="exampleModalLabel">
                  Breakdown
                </h1>
                <i
                  className="icofont-close btn-close"
                  onClick={() => {
                    handleClose();
                  }}
                ></i>
              </div>
              <form>
                <div className="modal-body modale-scroll">
                  <div className="form-design">
                    {show && <ApiLoder />}
                    <div className="d-flex align-items-center justify-content-between mb-30">
                      <div className="heading_width_search d-flex align-items-center gap-3">
                        <h2 className="body_heading width-left-border mb-0">
                          {data?.label}
                        </h2>
                      </div>
                      {token && tenantList?.length !== 0 && (
                        <div className="heading_width_search d-flex align-items-center gap-3">
                          <ExportFile
                            type="breakdown"
                            serach={""}
                            page={1}
                            perpage={10}
                            tenantId={""}
                            status={"2"}
                            Url={apiUrls.ExportContacts}
                            jobStatus={""}
                            vendor={""}
                            productType={""}
                            WindowProductId={data.windowProdcutId}
                            EstimationId={EstimateId}
                          />
                        </div>
                      )}
                    </div>
                    <div className="table-responsive">
                      <table className="table">
                        <thead style={{ whiteSpace: "nowrap" }}>
                          <tr>
                            <th scope="col">Product Type</th>
                            <th scope="col">Product</th>
                            <th scope="col">Window Qty</th>
                            <th scope="col">Product Width</th>
                            <th scope="col">Product Height</th>

                            {tenantList?.map((val, i) => (
                              <th scope="col" key={i}>
                              <Link className="color-blue" to={`/component/detail/${val.componentId}`} target="_blank">{val?.componentName}</Link>
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          <tr>
                            <td>{tenantList[0]?.productTypeName}</td>
                            <td><Link className="color-blue" to={`/products/detail/${tenantList[0]?.productId}`} target="_blank">{tenantList[0]?.productName}</Link></td>
                            <td>{tenantList[0]?.quantity}</td>
                            <td>{tenantList[0]?.buildWidth}</td>
                            <td>{tenantList[0]?.buildHeight}</td>
                            {tenantList?.map((val, i) => (
                              <td key={i}>{defaultConfig.currencySign} {val?.price || 0}</td>
                            ))}
                          </tr>
                        </tbody>
                      </table>
                    </div>

                    {(!tenantList || tenantList?.length === 0) && (
                      <div className="text-center border-0 no-records">
                        <img
                          src="/image/no-records.svg"
                          alt=" "
                          className="img-fluid"
                        />
                        <p className="font-14">No Breakdown available</p>
                      </div>
                    )}
                  </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      </Dialog>
    </>
  );
};

export default Breakdown;
